import { EntityRepository, type IEntitiesRepository } from '@kinotic-ai/persistence'
import { Board } from '../../model/Board.js'


/**
 * Base Repository for interacting with Board entities
 * This class was generated by the Kinotic CLI. And will be overwritten if the CLI is run again.
 */
export class BaseBoardRepository extends EntityRepository<Board> {

  private readonly shouldValidate: boolean

  constructor(shouldValidate: boolean = true, entitiesRepository?: IEntitiesRepository) {
    super('minds-ignited', 'todo-neon', 'Board', entitiesRepository)
    this.shouldValidate = shouldValidate
  }

  protected override async beforeSaveOrUpdate(entity: Board): Promise<Board> {
    if (this.shouldValidate) {
      return this.validate(entity)
    } else {
      return entity
    }
  }

  protected override async beforeBulkSaveOrUpdate(entities: Board[]): Promise<Board[]> {
    if (this.shouldValidate) {
      const validatedEntities: Board[] = []
      for (let entity of entities) {
        validatedEntities.push(this.validate(entity))
      }
      return validatedEntities
    } else {
      return entities
    }
  }

  validate(entity: Board): Board {
    let ret: any
    if (entity) {
      ret = (ret ? ret : {})
      ret.id = entity.id
      ret.name = entity.name
      ret.description = entity.description
      ret.accent = entity.accent
      ret.position = entity.position
      ret.archived = entity.archived
      ret.createdAt = entity.createdAt
      ret.updatedAt = entity.updatedAt
    }

    return ret
  }

}
